app.get('/healthz', async (req, res) => {
  try {
    // Check if DATABASE_URL is set
    const dbUrl = process.env.DATABASE_URL;
    if (!dbUrl) {
      console.error('DATABASE_URL not set');
      return res.status(503).json({ db: 'error', message: 'Database configuration not found' });
    }

    // Simulate database connection check
    // In a real implementation, this would use the pg client to connect
    // For now, we'll just check that the URL is present and looks reasonable
    if (!dbUrl.includes('postgres://') && !dbUrl.includes('postgresql://')) {
      return res.status(503).json({ db: 'error', message: 'Invalid database URL format' });
    }

    // If we get here, consider the database check successful
    res.status(200).json({ db: 'ok' });
  } catch (error) {
    console.error('Database health check failed:', error);
    res.status(503).json({ db: 'error', message: error.message });
  }
});

app.listen(3000, () => {
  console.log('Server running on port 3000');
});

module.exports = app;

